#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。

用法:
    python count_non_null.py data.csv
    python count_non_null.py data.csv --na "NA,N/A,null" --encoding utf-8-sig
"""

import argparse
import csv
import sys


def count_non_null(path, na_values=("",), encoding="utf-8-sig"):
    """返回 (表头, 每列非空计数 dict, 超出表头长度的单元格数)。"""
    na = {v.strip().lower() for v in na_values if v.strip()}
    with open(path, newline="", encoding=encoding) as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return [], {}, 0

        counts = {col: 0 for col in header}
        overflow = 0
        for row in reader:
            for i, cell in enumerate(row):
                if i < len(header):
                    if cell.strip().lower() not in na:
                        counts[header[i]] += 1
                else:
                    overflow += 1
    return header, counts, overflow


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument(
        "--na",
        default="",
        help="视为空值的字符串，逗号分隔，默认仅空字符串",
    )
    parser.add_argument("--encoding", default="utf-8-sig", help="文件编码，默认 utf-8-sig")
    args = parser.parse_args()

    try:
        header, counts, overflow = count_non_null(
            args.csv_file, na_values=tuple(args.na.split(",")), encoding=args.encoding
        )
    except FileNotFoundError:
        sys.exit("文件不存在: %s" % args.csv_file)

    if not header:
        sys.exit("CSV 文件为空")

    width = max(len(c) for c in header)
    for col in header:
        print("%-*s  %d" % (width, col, counts[col]))
    if overflow:
        print("超出表头列数的单元格: %d" % overflow)
    print("\n列数: %d" % len(header))


if __name__ == "__main__":
    main()
